code = r'''  // r20 `&m04bbank=1` (with m04foam + m04river): the painted bank foam — LOW, WIDE heaps of BIG separate glossy pearly
  // lilac-white bubbles with pale blue-lilac shading — as instanced Blender heaps (tools/blender/foam_bank04.py: 4 seeds in
  // assets/models/match04/foam_bank04.glb, ~5k triangles each; recipe from the lead's r19 m04bfoam test) in place of the
  // sprite cloud puffs: one heap per bank clump inside the entrance rim, the pre-opening foam banks binned into heaps (two
  // rows per side). Same visibility rule as all 3D foam (hidden in the approved view, fading in as the camera leaves it);
  // every bubble shrinks away into its own centre as it nears the camera (view depth m04bbn0 -> m04bbn1, default the
  // foam's m04foamn0 / m04foamn1, like the sprite bubbles) so nothing pops in the face. Tunables: m04bbs heap size,
  // m04bbb pre-opening bin length (u), m04bbe self-light, m04bbc tint (0 white .. 3 blue-lilac), m04bbi iridescence,
  // m04bbr roughness, m04bbk sink into the water (share of the heap height), m04bbw inside-rim heaps (0 = none).
  const buildBank = (clumps: { side: number; a: number; cl: number; reach: number }[], puffs: { side: number; x: number; z: number }[], nearF: number[]) => {
    let s3 = 24683; const r3 = () => ((s3 = (s3 * 16807) % 2147483647) / 2147483647);
    const HL = 3.42, HH = 1.0;                                  // heap length / height in the glb (u)
    const bs = M04.num('m04bbs', 1), sink = M04.num('m04bbk', 0.12);
    const place: { x: number; y: number; z: number; s: number; yaw: number; k: number }[] = [];
    if (M04.num('m04bbw', 1) > 0) for (const c of clumps) {
      const L = THREE.MathUtils.clamp(c.cl * 1.15, 1.4, 2.8) * bs, s = L / HL;
      const xi = Math.max(XF + 0.2, xW - 0.25 - 0.9 * s);         // inward from the wall, on the trough's rising side
      const tt = THREE.MathUtils.clamp((xi - XF) / Math.max(0.1, xW - XF), 0, 1);
      place.push({ x: cx + c.side * xi, y: 0.02 + RY * tt * tt - sink * HH * s, z: z0 - c.a - c.cl / 2, s, yaw: (r3() - 0.5) * 0.3, k: Math.floor(r3() * 4) });
    }
    const bL = M04.num('m04bbb', 1.75);
    const bins = new Map<string, { side: number; x: number; z: number; n: number }>();
    for (const p of puffs) {
      const dx = Math.abs(p.x - cx) - waterHalf;
      const key = `${p.side}:${Math.floor((p.z - z0 + 7) / bL)}:${dx < 1.3 ? 0 : 1}`;
      const b = bins.get(key) ?? { side: p.side, x: 0, z: 0, n: 0 };
      b.x += p.x; b.z += p.z; b.n++; bins.set(key, b);
    }
    for (const b of bins.values()) {
      if (b.n < 3) continue;
      const s = (1.9 + 0.9 * r3()) / HL * bs;
      place.push({ x: b.x / b.n, y: -sink * HH * s, z: b.z / b.n, s, yaw: (r3() - 0.5) * 0.4, k: Math.floor(r3() * 4) });
    }
    const holder = new THREE.Group(); holder.name = 'm04_bank_heaps'; holder.visible = false; group.add(holder);
    const near = new THREE.Vector2(M04.num('m04bbn0', nearF[0]), M04.num('m04bbn1', nearF[1]));
    const mat = new THREE.MeshPhysicalMaterial({
      vertexColors: true, color: new THREE.Color(['#ffffff', '#e4e2ff', '#d6e2ff', '#cfdcff'][Math.round(M04.num('m04bbc', 3))] ?? '#ffffff'),
      roughness: M04.num('m04bbr', 0.08), metalness: 0, clearcoat: 1, clearcoatRoughness: 0.08,
      iridescence: M04.num('m04bbi', 0.15), iridescenceIOR: 1.3,
      emissive: new THREE.Color('#eef3ff'), emissiveIntensity: M04.num('m04bbe', 0.2), transparent: true, depthWrite: true });
    mat.onBeforeCompile = (sh) => {
      sh.uniforms.uBNear = { value: near };
      sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nattribute vec4 aC;\nuniform vec2 uBNear;')
        .replace('#include <begin_vertex>', `#include <begin_vertex>
  {
    // r20 m04bbank: each bubble shrinks into its own centre as it nears the camera (view depth), like the sprite foam
    vec4 cv = viewMatrix * modelMatrix * instanceMatrix * vec4(aC.xyz, 1.0);
    transformed = aC.xyz + (transformed - aC.xyz) * smoothstep(uBNear.x, uBNear.y, -cv.z);
  }`);
    };
    updaters.push((a) => { holder.visible = a > 0.01; mat.opacity = a; });
    new GLTFLoader().loadAsync(new URL('../../assets/models/match04/foam_bank04.glb', import.meta.url).href).then((gl) => {
      const geos: THREE.BufferGeometry[] = [];
      gl.scene.updateMatrixWorld(true);
      gl.scene.traverse((n) => {
        const me = n as THREE.Mesh;
        if (!me.isMesh) return;
        const g = me.geometry.clone().applyMatrix4(me.matrixWorld);
        // per vertex: the centre + radius of the bubble it belongs to (connected pieces of the joined mesh)
        const pa = g.attributes.position as THREE.BufferAttribute, nV = pa.count, ix = g.index!.array;
        const par = new Int32Array(nV).map((_, i) => i);
        const f = (i: number) => { while (par[i] !== i) { par[i] = par[par[i]]; i = par[i]; } return i; };
        for (let t = 0; t < ix.length; t += 3) { const a = f(ix[t]); const b = f(ix[t + 1]); if (b !== a) par[b] = a; const c = f(ix[t + 2]); if (c !== a) par[c] = a; }
        const sum = new Map<number, number[]>();
        for (let i = 0; i < nV; i++) { const k = f(i), q = sum.get(k) ?? [0, 0, 0, 0, 0]; q[0] += pa.getX(i); q[1] += pa.getY(i); q[2] += pa.getZ(i); q[3]++; sum.set(k, q); }
        const aC = new Float32Array(nV * 4);
        for (let i = 0; i < nV; i++) {
          const q = sum.get(f(i))!, x = q[0] / q[3], y = q[1] / q[3], z = q[2] / q[3];
          aC.set([x, y, z, 0], i * 4);
        }
        g.setAttribute('aC', new THREE.Float32BufferAttribute(aC, 4));
        const m = /heap_(\d+)/.exec(me.name);
        geos[m ? Number(m[1]) : geos.length] = g;
      });
      const nG = geos.filter(Boolean).length || 1;
      const dummy = new THREE.Object3D();
      let tris = 0;
      geos.forEach((g, gi) => {
        if (!g) return;
        const mine = place.filter((p) => p.k % nG === gi);
        if (!mine.length) return;
        const im = new THREE.InstancedMesh(g, mat, mine.length);
        mine.forEach((p, i) => {
          // glb: length along +x, up +y; the river runs along -z -> yaw 90 deg (+ a little), mirrored on the left bank
          dummy.position.set(p.x, p.y, p.z); dummy.rotation.set(0, Math.PI / 2 + p.yaw, 0); dummy.scale.set(p.s, p.s, p.s * (p.x < cx ? -1 : 1));
          dummy.updateMatrix(); im.setMatrixAt(i, dummy.matrix);
        });
        im.instanceMatrix.needsUpdate = true; im.name = `m04_bank_heap_${gi}`; im.renderOrder = 3; im.frustumCulled = false;
        holder.add(im); tris += (g.index!.count / 3) * mine.length;
      });
      console.info('[match04] m04bbank', { heaps: place.length, seeds: nG, tris });
    }).catch((e) => console.error('[match04] m04bbank load failed', String(e)));
  };
'''
s = s.replace(anchor, anchor + code)
open(p,'w').write(s)
